def check_N(m):
    # N = 3m^2 + 8m + 4 - m^3
    N = 3 * m**2 + 8 * m + 4 - m**3
    if N < 0:
        return None

    # Check if N is a perfect square
    sqrt_N = int(N**0.5)
    if sqrt_N * sqrt_N == N:
        return sqrt_N
    return None

# Test m from -10 to 10, excluding m=0
solutions = {}
for m in range(-10, 11):
    if m == 0:
        continue

    sqrt_N = check_N(m)
    if sqrt_N is not None:
        solutions[m] = sqrt_N

print(solutions)

